const url = ($json.body && $json.body.twitter_url) || $json.twitter_url || '';
if (!url) {
  throw new Error('Missing twitter_url in webhook body.');
}
const m = url.match(/(?:twitter\.com|x\.com|mobile\.twitter\.com)\/([^/\?]+)\/status\/(\d+)/i);
if (!m) {
  throw new Error('Could not parse Twitter URL: ' + url);
}
return [{ json: { handle: m[1], tweet_id: m[2], source_url: url } }];

const xUserId = $('Resolve X User ID').first().json.id;
const wpUsers = $('Resolve WP User').first().json;
const wpUserId = wpUsers[0] && wpUsers[0].id;
const nickname = $('Lookup Artist').first().json.Wordpress_Nickname;
const handle = $('Parse Twitter URL').first().json.handle;
const targetTweetId = $('Parse Twitter URL').first().json.tweet_id;

const bearer = $env.X_BEARER_TOKEN;
if (!bearer) {
  throw new Error('X_BEARER_TOKEN env var is not set on the n8n host.');
}
if (!xUserId) throw new Error('Could not resolve X user id.');
if (!wpUserId) throw new Error('Could not resolve WP user id.');

const mediaByKey = {};
let paginationToken = null;
let foundTarget = false;
let pages = 0;
const MAX_PAGES = 10;
const allTweets = [];

while (pages < MAX_PAGES && !foundTarget) {
  pages++;
  const qs = new URLSearchParams({
    max_results: '100',
    'tweet.fields': 'created_at,attachments',
    expansions: 'attachments.media_keys',
    'media.fields': 'media_key,type,url,preview_image_url'
  });
  if (paginationToken) qs.set('pagination_token', paginationToken);
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.twitter.com/2/users/' + xUserId + '/tweets?' + qs.toString(),
    headers: { Authorization: 'Bearer ' + bearer },
    json: true
  });
  const tweets = resp.data || [];
  const media = (resp.includes && resp.includes.media) || [];
  for (const m of media) mediaByKey[m.media_key] = m;
  for (const t of tweets) {
    allTweets.push(t);
    if (String(t.id) === String(targetTweetId)) foundTarget = true;
  }
  if (foundTarget) break;
  if (!resp.meta || !resp.meta.next_token) break;
  paginationToken = resp.meta.next_token;
}

if (!foundTarget) {
  throw new Error('Tweet ' + targetTweetId + ' not found within ' + MAX_PAGES + ' pages.');
}

const rows = [];
for (const tweet of allTweets) {
  const keys = tweet.attachments && tweet.attachments.media_keys;
  if (!keys) continue;
  const urls = keys
    .map(k => mediaByKey[k])
    .filter(m => m && m.type === 'photo' && m.url)
    .map(m => m.url);
  if (!urls.length) continue;
  rows.push({
    json: {
      tweet_id: tweet.id,
      text: tweet.text || '',
      created_at: tweet.created_at,
      image_urls: urls,
      source_url: 'https://x.com/' + handle + '/status/' + tweet.id,
      Wordpress_Nickname: nickname,
      wp_user_id: wpUserId
    }
  });
}

if (!rows.length) {
  throw new Error('No tweets with images found.');
}
return rows;

const tweet = $json;

const wpUser = $env.WP_USER;
const wpAppPassword = $env.WP_APP_PASSWORD;
if (!wpUser || !wpAppPassword) {
  throw new Error('WP_USER and WP_APP_PASSWORD env vars are required.');
}
const auth = Buffer.from(wpUser + ':' + wpAppPassword).toString('base64');
const wpHeaders = { Authorization: 'Basic ' + auth };

const uploaded = [];
for (const imageUrl of tweet.image_urls) {
  const img = await this.helpers.httpRequest({
    method: 'GET',
    url: imageUrl,
    encoding: 'arraybuffer',
    json: false
  });
  const buf = Buffer.from(img.body || img);
  const filename = imageUrl.split('/').pop().split('?')[0] || 'image.jpg';
  const media = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://shad-base.com/wp-json/wp/v2/media',
    headers: {
      ...wpHeaders,
      'Content-Disposition': 'attachment; filename="' + filename + '"',
      'Content-Type': 'image/jpeg'
    },
    body: buf,
    json: true
  });
  uploaded.push({ id: media.id, source_url: media.source_url });
}

const created = new Date(tweet.created_at);
const title = 'Comic by ' + tweet.Wordpress_Nickname + ' - ' + created.toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });

const comic = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://shad-base.com/wp-json/wp/v2/comic',
  headers: { ...wpHeaders, 'Content-Type': 'application/json' },
  body: {
    title: title,
    status: 'draft',
    date: created.toISOString(),
    author: tweet.wp_user_id,
    featured_media: uploaded[0] && uploaded[0].id
  },
  json: true
});

const altText = (tweet.text || '').replace(/\s+/g, ' ').trim().slice(0, 200) || tweet.Wordpress_Nickname;
const escapeAttr = (s) => String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = uploaded.map(u => '<img src="' + u.source_url + '" alt="' + escapeAttr(altText) + '" class="alignnone" />').join('\n');

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://shad-base.com/wp-json/comic-easel/v1/comics/' + comic.id + '/meta',
  headers: { ...wpHeaders, 'Content-Type': 'application/json' },
  body: {
    source_tweet_id: String(tweet.tweet_id),
    source_url: tweet.source_url,
    ceo_html_below_comic: html
  },
  json: true
});

return [{ json: {
  tweet_id: tweet.tweet_id,
  comic_id: comic.id,
  image_count: uploaded.length,
  source_url: tweet.source_url
} }];
